QUESTIONS.push({"q":"How will you proceed in the given situation?","a":["you will turn last","the truck will pass first","you have priority"],"ro":{"q":"Cum veți proceda în situația dată?","a":["veți vira ultimul","camionul va trece primul","aveți prioritate"]},"correct":[2],"image":"data:image/jpeg;base64,","conf":"site-learned"});QUESTIONS.push({"q":"In what order will the cars travel through the intersections shown?","a":["blue, red, yellow","red, blue, yellow","yellow, red, blue"],"ro":{"q":"În ce ordine vor circula autoturismele prin intersecțiile prezentate?","a":["albastru, roșu, galben","roșu, albastru, galben","galben, roșu, albastru"]},"correct":[1],"image":"data:image/jpeg;base64,","conf":"site-learned"});QUESTIONS.push({"q":"The sign means:","a":["sounding the horn is allowed only to avoid an immediate danger","using the horn is allowed only during the day","using the horn is allowed only in conditions of reduced visibility"],"ro":{"q":"Indicatorul semnifică:","a":["claxonatul este permis numai în cazul evitării unui pericol imediat","folosirea claxonului este permisă numai pe timp de zi","folosirea claxonului este permisă numai în condiții de vizibilitate redusă"]},"correct":[0],"image":"data:image/jpeg;base64,","conf":"site-learned"});QUESTIONS.push({"q":"What do you do if you have positioned yourself in the left lane, even though you intend to turn right?","a":["signal, sound the horn, and turn right;","turn left;","since no vehicles are coming from the opposite direction, turn right while accelerating."],"ro":{"q":"Cum procedați dacă v-ați încadrat pe banda din stânga, deși intenționați să virați la dreapta?","a":["semnalizați, claxonați și virați la dreapta;","virați la stânga;","întrucât din sens opus nu circulă alte vehicule, virați accelerat la dreapta."]},"correct":[1],"image":"data:image/jpeg;base64,","conf":"site-learned"});QUESTIONS.push({"q":"How do you proceed in this situation?","a":["it is recommended to increase your attention","stop","accelerate, so as not to be caught by falling rocks"],"ro":{"q":"Cum procedați în această situație?","a":["se recomandă să măriți atenția","opriți","accelerați, pentru a nu fi surprins de căderea pietrelor"]},"correct":[0],"image":"data:image/jpeg;base64,","conf":"site-learned"});QUESTIONS.push({"q":"How is it recommended you behave in this situation?","a":["stop only if the ball comes to rest on the roadway","reduce speed and be prepared to stop","keep driving, since children are forbidden to enter the roadway"],"ro":{"q":"Cum se recomandă să vă comportați în această situație?","a":["opriți numai în cazul în care mingea se oprește pe carosabil","reduceți viteza și vă pregătiți să opriți","circulați mai departe, întrucât copiilor le este interzis să intre pe carosabil"]},"correct":[1],"image":"data:image/jpeg;base64,","conf":"site-learned"});QUESTIONS.push({"q":"Can you overtake in this situation?","a":["no, because you are in the area of a level crossing","no, because you are less than 150 m from the railway","yes, it is permitted"],"ro":{"q":"Puteţi depăşi în această situaţie?","a":["nu, deoarece vă aflaţi în zona unei treceri la nivel cu calea ferată","nu, deoarece vă aflaţi la mai puţin de 150 m de calea ferată","da, este regulamentar"]},"correct":[2],"image":"data:image/jpeg;base64,","conf":"site-learned"});QUESTIONS.push({"q":"Signals given from a police vehicle escorting an official convoy, using special audible and visual warning devices, require:","a":["leaving the road at the first street to the right;","stopping immediately off the carriageway or as close as possible to the curb or shoulder, until the convoy has passed;","reducing speed and moving as close as possible to the curb or shoulder."],"ro":{"q":"Semnalele date dintr-un autovehicul al poliției, care însoțește o coloană oficială de vehicule, prin folosirea mijloacelor speciale de avertizare sonoră și luminoasă, obligă la:","a":["părăsirea drumului pe prima stradă la dreapta;","oprirea, de îndată, în afara părții carosabile sau cât mai aproape de bordură ori acostament, până la trecerea coloanei;","reducerea vitezei și deplasarea cât mai aproape de bordură sau acostament."]},"correct":[1],"image":null,"conf":"site-learned"});QUESTIONS.push({"q":"How do you make sure there is no danger when reversing the vehicle?","a":["turn on the rear fog light;","sound the horn before moving off;","check to the front, to the rear, and to the sides."],"ro":{"q":"Cum vă asigurați că nu există niciun pericol atunci când manevrați vehiculul înapoi?","a":["aprindeți lanterna de ceață din spate;","claxonați înainte de a pleca;","vă asigurați din față, din spate și din lateral."]},"correct":[2],"image":null,"conf":"site-learned"});QUESTIONS.push({"q":"What is the correct way to proceed if, while inside a roundabout, you notice that a convoy with priority traffic status is traveling on a side road?","a":["you continue on your way, because you have the right of way in the roundabout;","you stop and give priority to the convoy with priority status;","you turn right and leave the intersection."],"ro":{"q":"Cum veți proceda corect dacă, aflându-vă în interiorul unei intersecții cu circulație în sens giratoriu, observați că pe un drum lateral circulă o coloană cu regim de circulație prioritară?","a":["vă continuați drumul, deoarece aveți prioritate de trecere în sensul giratoriu;","opriți și acordați prioritate coloanei cu regim prioritar;","virați la dreapta și părăsiți intersecția."]},"correct":[1],"image":null,"conf":"site-learned"});QUESTIONS.push({"q":"You may drive a vehicle in a pedestrian zone if:","a":["you are providing commercial services;","your lighting system is in working order;","you live in that zone."],"ro":{"q":"Puteți circula cu vehiculul într-o zonă pietonală dacă:","a":["prestați servicii comerciale;","aveți sistemul de iluminare în stare de funcționare;","locuiți în acea zonă."]},"correct":[2],"image":null,"conf":"site-learned"});QUESTIONS.push({"q":"You are required to carry in the vehicle / agricultural or forestry tractor:","a":["only the first-aid kit;","only the first-aid kit and warning triangles;","a first-aid kit, two warning triangles, and an approved fire extinguisher."],"ro":{"q":"Sunteți obligat să aveți în autovehicul / tractor agricol sau forestier:","a":["numai trusa medicală de prim ajutor;","numai trusa medicală de prim ajutor și triunghiuri reflectorizante;","o trusă medicală de prim ajutor, două triunghiuri reflectorizante și un stingător de incendiu omologat."]},"correct":[2],"image":null,"conf":"site-learned"});QUESTIONS.push({"q":"Is it advisable to keep or store certain objects on the floor of the vehicle / agricultural or forestry tractor?","a":["yes, as long as they don't interfere with operating the vehicle's controls;","yes, if there is nowhere else to put small objects;","no, because these objects could roll under the pedals and create dangerous situations."],"ro":{"q":"Este recomandabil să păstrăm sau să depozităm anumite obiecte pe podeaua autovehiculului / tractorului agricol sau forestier?","a":["da, atâta vreme cât acestea nu ne stânjenesc în acționarea comenzilor autovehiculului;","da, dacă nu mai există un alt loc în care să așezăm obiectele de mici dimensiuni;","nu, întrucât există posibilitatea rostogolirii acestor obiecte, care pot ajunge sub pedale și crea situații periculoase."]},"correct":[2],"image":null,"conf":"site-learned"});QUESTIONS.push({"q":"What goods are subject to confiscation, in accordance with the traffic law?","a":["special light and sound warning devices held illegally;","unauthorized supplementary headlights and unauthorized supplementary roof rack;","technical devices for detecting the presence of radar equipment."],"ro":{"q":"Ce bunuri sunt supuse confiscării, în conformitate cu legea circulaţiei?","a":["mijloacele speciale de avertizare luminoasă şi sonoră deţinute ilegal;","farurile suplimentare şi portbagajul suplimentar neautorizat;","mijloacele tehnice de detectare a prezenţei aparatelor radar."]},"correct":[0],"image":null,"conf":"site-learned"});QUESTIONS.push({"q":"The driving license is withdrawn by the traffic police in the following cases:","a":["When the authorized medical facility, following the required specialist examination, establishes that the license holder is medically fit to drive a vehicle;","When the administrative validity of the driving license has expired;","When the holder could not be tested to determine the pure alcohol concentration in exhaled air, and the medical examination found clinical signs specific to recent consumption of alcoholic beverages."],"ro":{"q":"Retragerea permisului de conducere se dispune de către poliția rutieră în următoarele cazuri:","a":["Atunci când unitatea de asistență medicală autorizată, în urma examenului de specialitate necesar stabilește că persoana care posedă permis de conducere este aptă medical pentru a conduce un autovehicul;","Atunci când valabilitatea administrativă a permisului de conducere a expirat;","În cazul în care titularul acestuia nu a putut fi supus testării în vederea stabilirii concentrației de alcool pur în aerul expirat, iar în urma examinării medicale s-au constatat elemente clinice specifice consumului recent de băuturi alcoolice."]},"correct":[2],"image":null,"conf":"site-learned"});QUESTIONS.push({"q":"For which of the following acts do administrative (non-criminal) sanctions apply?","a":["driving on public roads a motor vehicle / agricultural or forestry tractor under the influence of alcoholic beverages, if the act does not constitute a criminal offence under the law;","putting into circulation or driving on public roads an unregistered motor vehicle;","driving on public roads a motor vehicle by a person without a driving license."],"ro":{"q":"Pentru care dintre faptele de mai jos se aplică sancțiuni contravenționale?","a":["conducerea pe drumurile publice a  unui autovehicul / tractor agricol sau forestier sub influența băuturilor alcoolice, dacă fapta nu constituie, potrivit legii, infracțiune;","punerea în circulație sau conducerea pe drumurile publice a unui autovehicul neînmatriculat;","conducerea pe drumurile publice a unui autovehicul de către o persoană fără permis de conducere."]},"correct":[0],"image":null,"conf":"site-learned"});QUESTIONS.push({"q":"Voluntary stopping is forbidden:","a":["less than 50 m from the corner of the intersection;","in a place where it blocks the visibility of a traffic light signal;","in bends with visibility under 100 m."],"ro":{"q":"Oprirea voluntară este interzisă:","a":["la mai puțin de 50 m de colțul intersecției;","în locul în care se împiedică vizibilitatea unui semnal luminos;","în curbe cu vizibilitatea sub 100 m."]},"correct":[1],"image":null,"conf":"site-learned"});QUESTIONS.push({"q":"The sign in the image means:","a":["\"Children\";","\"Other dangers\";","\"Traffic jam\"."],"ro":{"q":"Indicatorul din imagine semnifică:","a":["„Copii“;","„Alte pericole“;","„Ambuteiaj“."]},"correct":[1],"image":"data:image/png;base64,","conf":"site-learned"});QUESTIONS.push({"q":"What obligations do you have when you encounter this sign?","a":["not to exceed a speed of 50 km/h, because a particularly dangerous curve to the right follows;","to reduce speed to 40 km/h and drive with low-beam (dipped) headlights;","not to overtake freight transport vehicles."],"ro":{"q":"Ce obligații aveți la întâlnirea indicatorului?","a":["să nu depășiți viteza de 50 km/h, deoarece urmează o curbă deosebit de periculoasă spre dreapta;","să reduceți viteza până la 40 km/h și să circulați cu faza de întâlnire;","să nu depășiți vehiculele de transport de mărfuri."]},"correct":[0],"image":"data:image/jpeg;base64,","conf":"site-learned"});QUESTIONS.push({"q":"What maneuvers are forbidden on the highway?","a":["using the acceleration lane to change direction of travel;","driving or stopping on the emergency lane, except in justified cases;","traveling at a speed lower than the maximum permitted limit."],"ro":{"q":"Ce manevre sunt interzise pe autostradă?","a":["folosirea benzii de accelerare pentru a schimba direcţia de mers;","circulaţia sau staţionarea pe banda de urgenţă, cu excepţia cazurilor justificate;","deplasarea cu o viteză inferioară limitei maxime permise."]},"correct":[1],"image":null,"conf":"site-learned"});QUESTIONS.push({"q":"In what situation is the immobilisation of the vehicle ordered?","a":["when there is data or evidence that it is the subject of a contravention;","when the technical condition of the vehicle seriously endangers road safety;","when it is unable to move because of engine faults."],"ro":{"q":"În ce situație se dispune imobilizarea vehiculului?","a":["când există date sau indicii că acesta face obiectul unei contravenții;","când starea tehnică a vehiculului pune în pericol grav siguranța circulației;","când este în imposibilitatea de a se deplasa, din cauza unor defecțiuni la motor."]},"correct":[1],"image":null,"conf":"site-learned"});QUESTIONS.push({"q":"What are your obligations at the signal of the railway agent at level crossings, given with a red-light device or with the fluorescent-reflective baton?","a":["to reduce speed only until you cross the railway;","to stop the vehicle;","to reduce speed and stop only if a railway vehicle is running."],"ro":{"q":"Ce obligații vă revin la semnalul agentului de cale ferată de la trecerile la nivel, executat cu un dispozitiv cu lumină roșie ori cu bastonul fluorescent-reflectorizant?","a":["să reduceți viteza doar până traversați calea ferată;","să opriți autovehiculul;","să reduceți viteza și să opriți numai dacă circulă un vehicul feroviar."]},"correct":[1],"image":null,"conf":"site-learned"});QUESTIONS.push({"q":"Aggressive behaviour of a driver on public roads means performing one of the following manoeuvres:","a":["Driving the vehicle below the legal speed limit;","Repeated use of sound and/or light signals that unjustifiably force the driver of the vehicle in front to vacate the traffic lane.","The moped or motorcycle rider having only one of the wheels in contact with the carriageway."],"ro":{"q":"Prin comportament agresiv al conducătorului auto pe drumurile publice se înțelege efectuarea uneia dintre umătoarele manevre:","a":["Conducerea vehiculului sub limita legală de viteză;","Folosirea repetată a semnalelor sonore și/sau luminoase de natură a obliga în mod nejustificat conducătorul de vehicul care circulă în fața sa, să elibereze banda de circulație.","Conducătorul mopedului sau motocicletei având în contact cu partea carosabilă numai una dintre roți."]},"correct":[1,2],"image":null,"conf":"site-learned"});